\label{thm:main1}
Let $A = KQ/I$ be a monomial algebra.
Then the following are equivalent:
\begin{itemize}\itemsep2mm

\item[(i)]
$E(M) = E^-(M)$ for all $M \in \operatorname{mod}(A)$ {\rm (= (S1))};

\item[(ii)]
$\operatorname{\tau-reg}(A) = \text{$\tau^-$-$\operatorname{reg}(A)$}$ {\rm (= (S2))};

\item[(iii)]
$\operatorname{Irr}^\tau(A) = \operatorname{Irr}^{\tau^-}(A)$ {\rm (= (S3))};

\item[(iv)]
$A \cong {\mathcal P}(Q,\tilde{W})$ for some hyperpotential $\tilde{W}$.

\end{itemize}

\label{prop:introhereditary1}
Suppose that $\operatorname{gl.dim}(A) < \infty$.
Then the following are equivalent:
\begin{itemize}\itemsep2mm

\item[(i)]
$E(M) = E^-(M)$ for all $M \in \operatorname{mod}(A)$;

\item[(ii)]
$\operatorname{\tau-reg}(A) = \text{$\tau^-$-$\operatorname{reg}(A)$}$;

\item[(iii)]
$\operatorname{Irr}^\tau(A) = \operatorname{Irr}^{\tau^-}(A)$;

\item[(iv)]
$A$ is hereditary.

\end{itemize}

\label{prop:introhereditary2}
The following are equivalent:
\begin{itemize}\itemsep2mm

\item[(i)]
$E(M,N) = E^-(M,N)$ for
all $M,N \in \operatorname{mod}(A)$;

\item[(ii)]
$A$ is hereditary.

\end{itemize}

\label{prop:hereditary2}
The following are equivalent:
\begin{itemize}\itemsep2mm

\item[(i)]
$E(M,N) = E^-(M,N)$ for
all $M,N \in \operatorname{mod}(A)$;

\item[(ii)]
$A$ is hereditary.

\end{itemize}

\label{prop:hereditary1}
Suppose that $\operatorname{gl.dim}(A) < \infty$.
Then the following are equivalent:
\begin{itemize}\itemsep2mm

\item[(i)]
$E(M) = E^-(M)$ for all $M \in \operatorname{mod}(A)$;

\item[(ii)]
$\operatorname{\tau-reg}(A) = \text{$\tau^-$-$\operatorname{reg}(A)$}$;

\item[(iii)]
$\operatorname{Irr}^\tau(A) = \operatorname{Irr}^{\tau^-}(A)$;

\item[(iv)]
$A$ is hereditary.

\end{itemize}

\label{cor:loops}
Let $KQ/I$ be a monomial algebra which is $1$-Iwanaga-Gorenstein.
Then the following hold:
\begin{itemize}\itemsep2mm

\item[(i)]
Each loop $h \in Q_1$ forms a relation cycle $C = h$ for $A$;

\item[(ii)] 
For each $k \in Q_0$, there is at most one loop $h \in Q_1$ 
with $s(h) = k$.

\end{itemize}

\label{thm:monomial3}
Let $A = KQ/I$ be a monomial algebra.
Then the following are equivalent:
\begin{itemize}\itemsep2mm

\item[(i)]
$E(M) = E^-(M)$ for all $M \in \operatorname{mod}(A)$ {\rm (= (S1))};

\item[(ii)]
$\operatorname{\tau-reg}(A) = \tau^-$-$\operatorname{reg}(A)$ {\rm (= (S2))};

\item[(iii)]
$\operatorname{Irr}^\tau(A) = \operatorname{Irr}^{\tau^-}(A)$ {\rm (= (S3))};

\item[(iv)]
$A \cong {\mathcal P}(Q,\tilde{W})$ for some hyperpotential $\tilde{W}$.

\end{itemize}

\label{thm:monomial4}
Let $A = KQ/I$ be a monomial algebra.
Then the following are equivalent:
\begin{itemize}\itemsep2mm

\item[(i)]
$A$ is $2$-Calabi-Yau tilted;

\item[(ii)]
$A$ is $1$-Iwanaga-Gorenstein and stably $3$-Calabi-Yau;

\item[(iii)]
$A \cong {\mathcal P}(Q,\tilde{W})$ for some hyperpotential $\tilde{W}$.

\end{itemize}

\label{thm:GSS}
Assume that $A$ is connected and not semisimple.
For $m \ge 1$, 
the following are equivalent:
\begin{itemize}\itemsep2mm

\item[(i)]
$\Omega_A^m(A/J(A)) \cong A/J(A)$;

\item[(ii)]
$A$ is twisted $m$-periodic.

\end{itemize}

\label{prop:selfinjective}
Let $A$ be selfinjective and $E$-symmetric.
We also assume that $A$ is connected and not semisimple.
Then the following hold:
\begin{itemize}\itemsep2mm

\item[(i)]
For each simple $A$-module $S$, we have $\tau_A^2(S) \cong \nu_A(S)$;

\item[(ii)]
$A$ is twisted $4$-periodic.

\end{itemize}
